import"./chunk-7CGTOI24.js";var e={slug:"review-arcane-a-melhor-adaptacao-de-game",title:"Review: Arcane continua sendo a melhor adapta\xE7\xE3o de game j\xE1 feita",dek:"Duas temporadas, 18 epis\xF3dios e uma hist\xF3ria completa. Revisitamos a s\xE9rie de League of Legends que mudou o que se espera de anima\xE7\xE3o adulta.",section:"series",kind:"review",tags:["Anima\xE7\xE3o","Netflix","Adapta\xE7\xE3o","Riot Games"],date:"2026-10-20",hero:{ref:"tv:94605",pick:0,alt:"Vi e Jinx em cena de Arcane"},score:9.5,verdict:{summary:"Anima\xE7\xE3o deslumbrante, personagens complexos e uma hist\xF3ria fechada do come\xE7o ao fim. N\xE3o precisa conhecer League of Legends para se apaixonar.",good:["Anima\xE7\xE3o que mistura 2D e 3D com estilo pr\xF3prio","A rela\xE7\xE3o entre Vi e Jinx como centro emocional","Final que fecha a hist\xF3ria sem enrola\xE7\xE3o"],bad:["Segunda temporada acelera tramas que pediam mais espa\xE7o","Alguns coadjuvantes somem no meio do caminho"]},body:[{p:"Quando *Arcane* estreou na Netflix, em novembro de 2021, a expectativa era baixa: uma s\xE9rie animada feita para vender um jogo competitivo. Tr\xEAs anos depois, com a segunda e \xFAltima temporada encerrada em novembro de 2024, ficou claro que a s\xE9rie era outra coisa. Hoje, *Arcane* \xE9 a r\xE9gua pela qual medimos qualquer adapta\xE7\xE3o de videogame."},{ficha:"tv:94605"},{h2:"Duas cidades, duas irm\xE3s"},{p:"A hist\xF3ria se divide entre Piltover, a cidade do progresso, e Zaun, a cidade subterr\xE2nea que sustenta esse progresso com mis\xE9ria. No meio est\xE3o Vi e Powder, irm\xE3s \xF3rf\xE3s de Zaun cujo v\xEDnculo se parte de forma violenta. Powder se torna Jinx, e a s\xE9rie inteira \xE9, no fundo, sobre o que restou daquelas duas meninas."},{p:"Hailee Steinfeld d\xE1 voz a Vi e Ella Purnell a Jinx, no original. Kevin Alejandro \xE9 Jayce, Katie Leung \xE9 Caitlyn e Harry Lloyd \xE9 Viktor, dois cientistas cuja descoberta muda o equil\xEDbrio entre as cidades."},{img:"tv:94605",pick:2,caption:"Piltover e Zaun t\xEAm identidades visuais opostas. Imagem de divulga\xE7\xE3o."},{h2:"A anima\xE7\xE3o"},{p:"O est\xFAdio franc\xEAs Fortiche criou um estilo que parece pintura em movimento: personagens em 3D com texturas desenhadas, efeitos em 2D, cores que mudam conforme o estado mental de quem est\xE1 em cena. As sequ\xEAncias que mostram a cabe\xE7a de Jinx s\xE3o das coisas mais criativas j\xE1 feitas em anima\xE7\xE3o para TV."},{quote:"Arcane n\xE3o pede que voc\xEA conhe\xE7a o jogo. Pede s\xF3 que voc\xEA se importe com duas irm\xE3s. O resto vem junto."},{h2:"M\xFAsica como linguagem"},{p:"A trilha \xE9 outro acerto. A abertura com *Enemy*, do Imagine Dragons, virou hit fora do p\xFAblico de games, e a s\xE9rie usa can\xE7\xF5es originais como parte da narrativa, em montagens que resumem anos de hist\xF3ria em poucos minutos. Raramente uma adapta\xE7\xE3o de jogo teve tanta personalidade sonora."},{h2:"A segunda temporada"},{p:"Assim como a primeira, a temporada final chegou dividida em tr\xEAs atos, lan\xE7ados em semanas seguidas de novembro de 2024. \xC9 mais ambiciosa e mais apressada."},{p:"Algumas tramas pol\xEDticas se resolvem r\xE1pido demais e personagens secund\xE1rios perdem espa\xE7o. Mesmo assim, o final \xE9 corajoso e fecha a hist\xF3ria de forma coerente, algo raro em s\xE9ries que dependem de franquias."},{h2:"Veredito"},{p:"*Arcane* \xE9 uma s\xE9rie completa, sem pontas soltas que dependam de renova\xE7\xE3o, e isso por si s\xF3 j\xE1 a torna uma \xF3tima maratona. Some a isso a melhor anima\xE7\xE3o da TV recente e um elenco de vozes impec\xE1vel. Nota 9,5."},{p:"Quer mais? Veja o nosso [ranking das melhores s\xE9ries baseadas em games](/artigo/series-baseadas-em-games-ranking)."}]};var o={source:"TMDB + IGDB",updatedAt:"2026-11-10",calendar:[],games:{},movies:{},tv:{94605:{id:94605,name:"Arcane",original:"Arcane",overview:"Em meio ao conflito entre as cidades-g\xEAmeas de Piltover e Zaun, duas irm\xE3s lutam em lados opostos de uma guerra entre tecnologias m\xE1gicas e convic\xE7\xF5es incompat\xEDveis.",poster:"/m3Tzf6k537PnhOEwaSRNCSxedLS.jpg",backdrops:["/5cvnxEHT3e39DvT6ARw4GNCFrB0.jpg","/q8eejQcg1bAqImEV8jh8RtBD4uH.jpg","/4ACkRHJCMXdNUUBem3Z0n1CclKf.jpg","/3WrZvh1spUdyEsgukJxAuCKHAQb.jpg","/sYXLeu5usz6yEz0k00FYvtEdodD.jpg"],genres:["Anima\xE7\xE3o","Action & Adventure","Sci-Fi & Fantasy"],cert:"16",creators:["Christian Linke","Alex Yee"],cast:[{name:"Hailee Steinfeld",role:"Vi (voz)"},{name:"Ella Purnell",role:"Jinx (voz)"},{name:"Kevin Alejandro",role:"Jayce (voz)"},{name:"Toks Olagundoye",role:"Mel Medarda (voz)"},{name:"Harry Lloyd",role:"Viktor (voz)"},{name:"Katie Leung",role:"Caitlyn (voz)"}],networks:["Netflix"],first:"2021-11-06",last:"2024-11-23",status:"Encerrada",seasons:2,episodes:18,next:null,country:"US"}}};export{o as media,e as post};
